package gen

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/format"
	"path"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/elauven/vela/app"
	"github.com/elauven/vela/ssr_runtime/pkgpath"
)

// Marker is the first line of every file the generator owns. A file
// without it is never overwritten or removed.
const Marker = "Code generated by vela-app. DO NOT EDIT."

// Output is one generated file.
type Output struct {
	Path string // relative to the project root
	Data []byte
}

// Outputs renders the four generated files (docs/APP.md R-2, P-15).
func (m *Model) Outputs() ([]Output, error) {
	goFile, err := m.routesGo()
	if err != nil {
		return nil, err
	}
	return []Output{
		{path.Join(m.Config.Out, "VelaApp.vela"), m.velaApp()},
		{path.Join(m.Config.Out, "routes.js"), m.routesJS()},
		{path.Join(m.Config.Out, "client.js"), m.clientJS()},
		{path.Join(m.Config.GoPackage, "routes_gen.go"), goFile},
	}, nil
}

// relImport is the import specifier of a project file from the out
// directory.
func (m *Model) relImport(file string) string {
	rel, err := filepath.Rel(filepath.FromSlash(m.Config.Out), filepath.FromSlash(file))
	if err != nil {
		return file
	}
	rel = filepath.ToSlash(rel)
	if !strings.HasPrefix(rel, ".") {
		rel = "./" + rel
	}
	return rel
}

// jsString quotes a string for JavaScript with single quotes.
func jsString(s string) string {
	quoted, _ := json.Marshal(s)
	inner := string(quoted[1 : len(quoted)-1])
	inner = strings.ReplaceAll(inner, `\"`, `"`)
	inner = strings.ReplaceAll(inner, `'`, `\'`)
	return "'" + inner + "'"
}

// velaApp is the app root (R-2): layouts imported statically, pages and
// error pages with lazy(), and one <vela:component> per level.
func (m *Model) velaApp() []byte {
	var b bytes.Buffer
	if m.Config.TypeScript {
		b.WriteString("<script lang=\"ts\">\n")
	} else {
		b.WriteString("<script>\n")
	}
	b.WriteString("  // " + Marker + "\n")
	fmt.Fprintf(&b, "  // The app root of %s (docs/APP.md R-2).\n", m.Config.Routes)
	lazy := false
	for _, c := range m.Components {
		lazy = lazy || c.Kind != KindLayout
	}
	if lazy {
		b.WriteString("  import { lazy } from 'vela';\n")
	}
	for _, c := range m.Components {
		if c.Kind == KindLayout {
			fmt.Fprintf(&b, "  import { Layout as %s } from %s;\n", c.Local, jsString(m.relImport(c.File)))
		}
	}
	b.WriteString("\n")
	for _, c := range m.Components {
		if c.Kind != KindLayout {
			fmt.Fprintf(&b, "  const %s = lazy(() => import(%s));\n", c.Local, jsString(m.relImport(c.File)))
		}
	}
	if lazy {
		b.WriteString("\n")
	}
	if m.Config.TypeScript {
		// The props of the router (R-1); the levels' own types are in
		// their $types (TS-8.2).
		b.WriteString("  export let route: any = null;\n  export let chain: { id: string; data?: unknown; error?: unknown; form?: unknown }[] = [];\n  export let start: number = 0;\n")
		b.WriteString("  // Client only (task 077): component values by level, such as a\n  // fragment of the server, which replace the table's component.\n  export let views: Record<number, any> = {};\n\n")
		b.WriteString("  const components: Record<string, any> = {\n")
	} else {
		b.WriteString("  export let route = null;\n  export let chain = [];\n  export let start = 0;\n")
		b.WriteString("  // Client only (task 077): component values by level, such as a\n  // fragment of the server, which replace the table's component.\n  export let views = {};\n\n")
		b.WriteString("  const components = {\n")
	}
	for _, c := range m.Components {
		fmt.Fprintf(&b, "    %s: %s,\n", jsString(c.ID), c.Local)
	}
	b.WriteString("  };\n</script>\n\n<template>\n")
	depth := max(m.Depth, 1)
	for i := range depth {
		at := "start"
		if i > 0 {
			at = fmt.Sprintf("start + %d", i)
		}
		indent := strings.Repeat("  ", i+1)
		close := ">"
		if i == depth-1 {
			close = " />"
		}
		fmt.Fprintf(&b, "%s<vela:component :this={views[%s] || components[chain[%s]?.id]} :data={chain[%s]?.data} :error={chain[%s]?.error} :form={chain[%s]?.form || null} :route={route}%s\n", indent, at, at, at, at, at, close)
	}
	for i := depth - 2; i >= 0; i-- {
		fmt.Fprintf(&b, "%s</vela:component>\n", strings.Repeat("  ", i+1))
	}
	b.WriteString("</template>\n")
	return b.Bytes()
}

// jsRoute and jsPattern are the JSON shapes of routes.js, which the shared
// fixtures read too.
type jsLevel struct {
	ID    string `json:"id"`
	Error string `json:"error,omitempty"`
}

type jsRoute struct {
	ID    string    `json:"id"`
	Chain []jsLevel `json:"chain"`
	// Render is the route's Render mode when the generator can read it
	// (L-7); the router loads the modules of a data route early.
	Render string `json:"render,omitempty"`
}

type jsSegment struct {
	Kind    string `json:"kind"`
	Value   string `json:"value"`
	Matcher string `json:"matcher,omitempty"`
}

type jsPattern struct {
	Route    int         `json:"route"`
	Segments []jsSegment `json:"segments"`
}

var segmentKinds = map[app.SegmentKind]string{app.Static: "static", app.Param: "param", app.Rest: "rest"}

// JSTable is the data of routes.js: the routes and the ranked patterns.
func (m *Model) JSTable() (routes []jsRoute, patterns []jsPattern) {
	for _, r := range m.Routes {
		route := jsRoute{ID: r.ID, Chain: []jsLevel{}, Render: r.RenderMode}
		for _, l := range r.Chain {
			route.Chain = append(route.Chain, jsLevel{ID: l.ID, Error: l.Error})
		}
		routes = append(routes, route)
	}
	for _, p := range m.Patterns {
		pattern := jsPattern{Route: p.Route, Segments: []jsSegment{}}
		for _, s := range p.Segments {
			pattern.Segments = append(pattern.Segments, jsSegment{Kind: segmentKinds[s.Kind], Value: s.Value, Matcher: s.Matcher})
		}
		patterns = append(patterns, pattern)
	}
	return routes, patterns
}

func jsonLine(v any) string {
	data, _ := json.Marshal(v)
	return string(data)
}

// routesJS is the client route table (P-15).
func (m *Model) routesJS() []byte {
	var b bytes.Buffer
	b.WriteString("// " + Marker + "\n")
	fmt.Fprintf(&b, "// The client route table of %s (docs/APP.md P-8, P-15).\n", m.Config.Routes)
	b.WriteString("import { lazy } from '@govela/runtime';\n")
	b.WriteString("import { builtinMatchers, matchPath } from '@govela/app/match';\n")
	for _, c := range m.Matchers {
		fmt.Fprintf(&b, "import { match as %s } from %s;\n", matcherLocal(c.Name), jsString(m.relImport(c.JSFile)))
	}
	b.WriteString("\n// The lazy components of VelaApp.vela: lazy() returns the value registered\n// under the same id, so the router loads the modules VelaApp renders.\n")
	b.WriteString("export const components = {\n")
	for _, c := range m.Components {
		if c.Kind != KindLayout {
			fmt.Fprintf(&b, "  %s: lazy(() => import(%s), %s),\n", jsString(c.ID), jsString(m.relImport(c.File)), jsString(c.ID))
		}
	}
	b.WriteString("};\n\n")
	routes, patterns := m.JSTable()
	b.WriteString("export const routes = {\n  routes: [\n")
	for _, r := range routes {
		fmt.Fprintf(&b, "    %s,\n", jsonLine(r))
	}
	b.WriteString("  ],\n  // In ranking order: the first full match wins.\n  patterns: [\n")
	for _, p := range patterns {
		fmt.Fprintf(&b, "    %s,\n", jsonLine(p))
	}
	b.WriteString("  ],\n  matchers: { ...builtinMatchers")
	for _, c := range m.Matchers {
		fmt.Fprintf(&b, ", %s: %s", strconv.Quote(c.Name), matcherLocal(c.Name))
	}
	b.WriteString(" },\n")
	fmt.Fprintf(&b, "  error: %s,\n  depth: %d,\n  components,\n", jsonLine(m.Error), m.Depth)
	b.WriteString("  match(path) {\n    return matchPath(this, path);\n  },\n};\n")
	return b.Bytes()
}

func matcherLocal(name string) string { return "match_" + name }

// clientJS is the client entry (R-5).
func (m *Model) clientJS() []byte {
	var b bytes.Buffer
	b.WriteString("// " + Marker + "\n")
	b.WriteString("// The client entry of the app (docs/APP.md R-5).\n")
	b.WriteString("import { start } from '@govela/app/client';\n")
	b.WriteString("import { VelaApp } from './VelaApp.vela';\n")
	b.WriteString("import { routes } from './routes.js';\n\n")
	fmt.Fprintf(&b, "start({ VelaApp, routes, root: %s });\n", jsString(app.RootID))
	return b.Bytes()
}

// rootImportPath is the Go package of the generated VelaApp renderer.
func (m *Model) rootImportPath() (string, error) {
	rel := strings.TrimPrefix(m.Config.Out, m.Config.Project+"/")
	if m.Config.Project == "." {
		rel = m.Config.Out
	}
	encoded, err := pkgpath.EncodePath(rel)
	if err != nil {
		return "", err
	}
	return m.Config.SSRModule + "/components/" + encoded, nil
}

// routesGo is the Go route table: the same patterns as routes.js, the
// chains and the loaders of the mirrored tree.
func (m *Model) routesGo() ([]byte, error) {
	root, err := m.rootImportPath()
	if err != nil {
		return nil, err
	}
	aliases := map[string]string{}
	used := map[string]bool{"app": true, "io": true, "velaapp": true, "vela": true}
	alias := func(dir string) string {
		if a, ok := aliases[dir]; ok {
			return a
		}
		base := pkgpath.PackageName(strings.NewReplacer("/", "_", ".", "_").Replace(dir))
		a := base
		for n := 2; used[a]; n++ {
			a = fmt.Sprintf("%s%d", base, n)
		}
		used[a] = true
		aliases[dir] = a
		return a
	}
	var body bytes.Buffer
	body.WriteString("// Routes returns the route table for app.New.\nfunc Routes() app.Routes {\n\treturn app.Routes{\n\t\tRoutes: []app.Route{\n")
	levels := func(chain []*Level) {
		for _, l := range chain {
			fields := []string{"ID: " + strconv.Quote(l.ID)}
			if l.Error != "" {
				fields = append(fields, "Error: "+strconv.Quote(l.Error))
			}
			if l.LoaderPkg != "" {
				fields = append(fields, fmt.Sprintf("Loader: app.LoaderOf(%s.%s)", alias(l.LoaderPkg), l.Kind))
			}
			if len(l.Params) > 0 {
				quoted := make([]string, len(l.Params))
				for i, p := range l.Params {
					quoted[i] = strconv.Quote(p)
				}
				fields = append(fields, "Params: []string{"+strings.Join(quoted, ", ")+"}")
			}
			if l.DepsPkg != "" {
				fields = append(fields, "Deps: "+alias(l.DepsPkg)+".Deps")
			}
			if l.Head {
				fields = append(fields, "Head: true")
			}
			if l.GuardPkg != "" {
				fields = append(fields, "Guard: "+alias(l.GuardPkg)+".Guard")
			}
			fmt.Fprintf(&body, "\t\t\t\t{%s},\n", strings.Join(fields, ", "))
		}
	}
	for _, r := range m.Routes {
		fmt.Fprintf(&body, "\t\t\t{ID: %s, Chain: []app.Level{\n", strconv.Quote(r.ID))
		levels(r.Chain)
		render := "app.RenderAuto"
		if r.RenderPkg != "" {
			render = alias(r.RenderPkg) + ".Render"
		}
		actions := ""
		if r.ActionsPkg != "" {
			actions = ", Actions: " + alias(r.ActionsPkg) + ".Actions()"
		}
		fmt.Fprintf(&body, "\t\t\t}, Render: %s%s},\n", render, actions)
	}
	body.WriteString("\t\t},\n\t\t// In ranking order: the first full match wins.\n\t\tPatterns: []app.Pattern{\n")
	kinds := map[app.SegmentKind]string{app.Static: "app.Static", app.Param: "app.Param", app.Rest: "app.Rest"}
	for _, p := range m.Patterns {
		if len(p.Segments) == 0 {
			fmt.Fprintf(&body, "\t\t\t{Route: %d},\n", p.Route)
			continue
		}
		segments := make([]string, len(p.Segments))
		for i, s := range p.Segments {
			segment := fmt.Sprintf("{Kind: %s, Value: %s", kinds[s.Kind], strconv.Quote(s.Value))
			if s.Matcher != "" {
				segment += ", Matcher: " + strconv.Quote(s.Matcher)
			}
			segments[i] = segment + "}"
		}
		fmt.Fprintf(&body, "\t\t\t{Route: %d, Segments: []app.Segment{%s}},\n", p.Route, strings.Join(segments, ", "))
	}
	body.WriteString("\t\t},\n\t\tMatchers: map[string]func(string) bool{\"int\": app.MatchInt, \"slug\": app.MatchSlug, \"uuid\": app.MatchUUID")
	for _, c := range m.Matchers {
		fmt.Fprintf(&body, ", %s: %s.Match", strconv.Quote(c.Name), alias(c.GoDir))
	}
	body.WriteString("},\n")
	fmt.Fprintf(&body, "\t\tError: %s,\n", strconv.Quote(m.Error))
	body.WriteString("\t\tNotFound: app.Route{Chain: []app.Level{\n")
	levels(m.NotFound)
	body.WriteString("\t\t}},\n")
	// The Go values of the route components, for static fragments (task
	// 077): the renderers vela --ssr writes under components/.
	componentAliases := map[string]string{}
	body.WriteString("\t\tComponents: map[string]vela.Component{\n")
	for _, c := range m.Components {
		dir, err := pkgpath.EncodePath(path.Dir(c.ID))
		if err != nil {
			return nil, err
		}
		importPath := m.Config.SSRModule + "/components/" + dir
		a, ok := componentAliases[importPath]
		if !ok {
			base := "c_" + pkgpath.PackageName(strings.NewReplacer("/", "_", ".", "_").Replace(dir))
			a = base
			for n := 2; used[a]; n++ {
				a = fmt.Sprintf("%s%d", base, n)
			}
			used[a] = true
			componentAliases[importPath] = a
		}
		fmt.Fprintf(&body, "\t\t\t%s: %s.%sComponent,\n", strconv.Quote(c.ID), a, path.Base(c.ID))
	}
	body.WriteString("\t\t},\n")
	fmt.Fprintf(&body, "\t\tDepth: %d,\n", m.Depth)
	rootID := m.Config.componentID(path.Join(m.Config.Out, "VelaApp.vela"))
	fmt.Fprintf(&body, "\t\tRoot:   app.Root{ID: %s, Render: renderRoot},\n", strconv.Quote(rootID))
	fmt.Fprintf(&body, "\t\tSource: %s,\n\t\tEntry:  %s,\n\t}\n}\n\n", strconv.Quote(m.Config.Project), strconv.Quote(path.Join(m.Config.Out, "client.js")))
	body.WriteString("func renderRoot(ctx context.Context, w io.Writer, props app.RootProps) error {\n")
	body.WriteString("\treturn velaapp.RenderVelaAppContext(ctx, w, velaapp.VelaAppProps{Route: props.Route, Chain: props.Chain, Start: float64(props.Start), Views: map[string]any{}}, velaapp.VelaAppSlots{})\n}\n")

	var b bytes.Buffer
	b.WriteString("// " + Marker + "\n\n")
	fmt.Fprintf(&b, "// Package %s is the route table of %s (docs/APP.md).\n", goPackageName(m.Config.GoPackage), m.Config.Routes)
	fmt.Fprintf(&b, "package %s\n\nimport (\n\t\"context\"\n\t\"io\"\n\n\t%q\n\tvela %q\n\n\tvelaapp %q\n", goPackageName(m.Config.GoPackage), AppImportPath, RuntimeImportPath, root)
	for _, dir := range sortedKeys(aliases) {
		fmt.Fprintf(&b, "\t%s %q\n", aliases[dir], m.Config.importPath(dir))
	}
	for _, importPath := range sortedKeys(componentAliases) {
		fmt.Fprintf(&b, "\t%s %q\n", componentAliases[importPath], importPath)
	}
	b.WriteString(")\n\n")
	b.Write(body.Bytes())
	formatted, err := format.Source(b.Bytes())
	if err != nil {
		return nil, fmt.Errorf("format routes_gen.go: %w\n%s", err, b.Bytes())
	}
	return formatted, nil
}

func goPackageName(dir string) string {
	return pkgpath.PackageName(path.Base(dir))
}
